import {withStableView} from './view-stability.mjs';
import {toolBanner} from './tool-banner.mjs';
import {chartTypes,exampleChart,parseTable,validateData,renderChart,csvText} from './research-model.mjs';
import {keys,list,projects,write,recordTask} from './state.mjs';
import {esc,icon,download,formatDate} from './ui.mjs';
let chart,root,ctx,tab='manual',mode='basic',dirty=false,busy=false,controller,formula='';
let researchEpoch=0,proDescription='',proType='',supplementalDirty=false;
const proTypes=['3D 建模渲染','仿真分析','光学成像','化学物理','地理信息','工程设计','建筑规划','机器学习','生物医学','电子电路','统计分析','自动化控制'];
const formulaTokens=[['分式','\\frac{a}{b}'],['根号','\\sqrt{x}'],['乘号','\\times'],['等号','='],['箭头','\\rightarrow'],['α','\\alpha'],['λ','\\lambda'],['上下标','x_{i}^{2}'],['矩阵','\\begin{bmatrix}a & b \\\\ c & d\\end{bmatrix}'],['函数','f(x)'],['求和','\\sum_{i=1}^{n} x_i'],['CO₂','\\mathrm{CO}_{2}'],['Na⁺','\\mathrm{Na}^{+}'],['H₂O','\\mathrm{H}_{2}\\mathrm{O}'],['Δ','\\Delta']];
export function disposeResearch(){researchEpoch++;controller?.abort();controller=null;root=null;dirty=false;busy=false;supplementalDirty=false;}
const $=s=>root?.querySelector(s);
export const researchHasWork=()=>!!root?.querySelector('.research-space')&&(dirty||supplementalDirty||busy);
export function researchRouteGuard(){if(!root?.querySelector('.research-space'))return true;if(busy){ctx.notify('正在处理，请稍候。');return false;}if((dirty||supplementalDirty)&&!confirm('有未保存的科研工具内容。确定离开并放弃这些修改？'))return false;dirty=false;supplementalDirty=false;return true;}
window.addEventListener('beforeunload',e=>{if(researchHasWork()){e.preventDefault();e.returnValue='';}});
export function mountResearch(context,id,projectId){disposeResearch();controller=new AbortController();ctx=context;const loaded=list(keys.drafts).find(d=>String(d.id)===String(id)&&d.tool==='research');chart=loaded?.chart?structuredClone(loaded.chart):exampleChart();chart.id=loaded?.id;chart.projectId=loaded?.projectId||projectId||'';if(loaded&&!loaded.chart){try{const data=parseTable('类别,数值\n'+loaded.material);Object.assign(chart,data,{title:loaded.title,example:false});}catch{ctx.notify('旧图表材料无法转换，请保留原记录并重新输入数据。');chart.id=undefined;}}dirty=false;busy=false;tab='manual';mode='basic';formula='';proDescription='';proType='';root=document.querySelector('.dashboard');draw();root.addEventListener('click',actions,{signal:controller.signal});root.addEventListener('input',inputChange,{signal:controller.signal});root.addEventListener('change',inputChange,{signal:controller.signal});}
function field(key,label,max=60){return `<label>${label}<input data-option="${key}" aria-label="${label}" value="${esc(chart[key])}" maxlength="${max}"></label>`;}
function nav(){return `<nav class="research-tools research-mode-cards" data-scroll-key="research-tools-1" aria-label="科研工具分类">${[['basic','chart','基础图表','从真实数据制作论文图表','本地绘图'],['pro','grid','专业图表','整理图形结构与绘制需求','需求整理'],['formula','file','公式编辑','编辑公式文本与导出 SVG','本地编辑']].map(([id,glyph,title,description,state],index)=>`<button data-mode="${id}" class="${mode===id?'active':''}" ${mode===id?'aria-current="page"':''}><span class="research-mode-art" aria-hidden="true">${icon(glyph,50)}</span><span class="research-mode-card-top"><span class="research-mode-icon">${icon(glyph,22)}</span><small>${state}</small></span><b>${title}</b><span class="research-mode-description">${description}</span><span class="research-mode-bottom">0${index+1} / ${id==='basic'?'数据可视化':id==='pro'?'绘图需求':'公式与符号'}${icon('arrow',15)}</span></button>`).join('')}</nav>`;}
function workflow(mode){const rows=mode==='pro'?[['选择领域','明确专业图表类型'],['描述结构','整理元素、关系与标注'],['导出需求','保留绘图说明文本']]:mode==='formula'?[['选择模板','插入常用公式与符号'],['编辑文本','核对公式内容与表达'],['复制导出','保存文本或 SVG']]:[['准备数据','输入表格或导入 CSV'],['调整图表','选择类型、配色与坐标'],['保存导出','保留数据与图表成果']];return `<ol class="research-workflow-strip" aria-label="${mode==='pro'?'专业图表需求':mode==='formula'?'公式编辑':'基础绘图'}操作步骤">${rows.map(([title,description],index)=>`<li><span>0${index+1}</span><div><b>${title}</b><small>${description}</small></div>${index<2?icon('arrow',14):''}</li>`).join('')}</ol>`;}
function statistics(){return chart.headers.slice(1).map((name,index)=>{const values=chart.rows.map(row=>String(row[index+1]??'').trim()).filter(value=>value!=='').map(Number).filter(Number.isFinite);const n=values.length;if(!n)return {name,n:0,mean:null,sd:null,min:null,max:null};const mean=values.reduce((sum,v)=>sum+v,0)/n;const variance=n>1?values.reduce((sum,v)=>sum+(v-mean)**2,0)/(n-1):0;return {name,n,mean,sd:Math.sqrt(variance),min:Math.min(...values),max:Math.max(...values)};});}
function statNumber(value){return value===null?'—':Number(value).toLocaleString('zh-CN',{maximumFractionDigits:4});}
function statCsv(rows){return '\ufeff'+[['系列','N','均值','标准差','最小值','最大值'],...rows.map(row=>[row.name,row.n,row.mean===null?'':row.mean,row.sd===null?'':row.sd,row.min===null?'':row.min,row.max===null?'':row.max])].map(row=>row.map(value=>`"${String(value).replaceAll('"','""')}"`).join(',')).join('\n');}
function drawStatistics(){const rows=statistics(),numericCount=rows.filter(row=>row.n>0).length;root.innerHTML=`<div class="research-space rdc-research-space rdc-research-stats">${toolBanner('research',{extraClass:'detail-service-banner',description:'整理研究数据，制作论文与汇报图表。',actions:`<a class="btn secondary" href="#assets?scope=local">${icon('chart',17)} 我的图表</a>`})}${nav()}<section class="card research-card research-stats-card"><div class="hub-card-heading"><div><h2>科研计算</h2><p class="research-section-subtitle">基于当前表格的本地描述统计，快速检查数据分布。</p></div><span class="hub-badge">${chart.example?'示例数据':'用户数据'}</span></div><div class="research-stats-summary"><div><span>当前数据</span><b>${esc(chart.title||'未命名图表')}</b></div><div><span>数据规模</span><b>${chart.rows.length} 行 · ${chart.headers.length-1} 个系列</b></div><div><span>可计算系列</span><b>${numericCount} 个</b></div></div><div class="research-stats-note">${icon('shield',17)} <div><b>这是本地描述统计</b><p>结果包含样本数、均值、样本标准差、最小值和最大值；不等同于显著性检验、回归分析或论文结论。</p></div></div><div class="research-stats-table-wrap" data-scroll-key="research-stats-table-wrap-1"><table class="research-stats-table"><thead><tr><th>数值系列</th><th>N</th><th>均值</th><th>标准差</th><th>最小值</th><th>最大值</th></tr></thead><tbody>${rows.map(row=>`<tr><th scope="row">${esc(row.name)}</th><td>${row.n}</td><td>${statNumber(row.mean)}</td><td>${statNumber(row.sd)}</td><td>${statNumber(row.min)}</td><td>${statNumber(row.max)}</td></tr>`).join('')}</tbody></table></div><p class="hub-footnote">空白单元格和非数字内容会被忽略；标准差使用样本标准差（n−1）。如需统计显著性检验，请结合专业软件或导师要求复核。</p><div class="research-actions research-stats-actions"><button class="btn secondary" data-mode="chart">${icon('chart',14)} 返回科研绘图</button><button class="btn secondary" data-action="stats-csv">导出统计 CSV</button><button class="btn primary" data-action="stats-json">导出统计 JSON</button></div></section><section class="card research-card research-stats-source"><div class="hub-card-heading"><h2>当前数据来源</h2><span class="hub-badge">${chart.headers.length-1} 个数值系列</span></div><p>统计结果实时读取“科研绘图”中的表格数据。你可以返回绘图页修改或导入数据，再回来重新计算。</p><div class="research-source-chips">${chart.headers.slice(1).map((name,index)=>`<span>${esc(name)} · ${rows[index].n} 个有效值</span>`).join('')}</div></section></div>`;}
function drawPro(){root.innerHTML=`<div class="research-space research-commerce rdc-research-space ${mode==='pro'?'rdc-research-pro':'rdc-research-formula'}">${toolBanner('research',{extraClass:'detail-service-banner',description:'记录图表类型、结构与关系，整理专业绘图需求。',actions:`<a class="btn secondary" href="#assets?scope=local">${icon('chart',17)} 我的图表</a>`})}${nav()}${workflow(mode)}<div class="research-commerce-main"><div class="research-banner">${icon('speaker',16)} 专业图表需求整理：记录图表类型、结构与关系。在线生成尚未开放。</div><section class="card research-pro-card"><div class="research-lang-tabs rdc-workspace-heading"><span class="rdc-workspace-symbol">${icon('grid',23)}</span><div><span class="research-panel-step">DRAWING BRIEF · 需求工作区</span><h2>把绘图需求说清楚</h2><p>说明要画什么，以及元素之间如何关联。</p></div><span class="research-language-label">支持中英文描述</span></div><div class="research-pro-form"><div class="research-pro-types"><b>选择专业领域</b><p class="rdc-picker-note">为需求标注所属领域</p>${proTypes.map((x,i)=>`<button class="${proType===String(i)?'active':''}" data-pro-type="${i}" aria-pressed="${proType===String(i)}">${x}<span>＋</span></button>`).join('')}</div><label class="research-pro-description"><span class="rdc-field-caption"><b>图表描述</b><em>用途 · 元素 · 关系 · 标注</em></span><textarea data-pro-description aria-label="专业图表需求描述" rows="15" maxlength="2000" placeholder="请详细描述你需要生成的图表内容…\n示例：\n- 对于电路图：描述电路元件及其连接关系\n- 对于细胞机制图：描述细胞各部分及其相互作用关系">${esc(proDescription)}</textarea><small>${proDescription.length}/2000</small></label></div><div class="research-pro-actions"><button class="btn primary research-generate" data-action="pro-export">${icon('file',16)} 导出绘图需求</button><button class="btn secondary" data-action="pro-generate">检查需求</button></div><p class="research-credit">在线生成待开放 · 当前整理与导出需求，不发起扣费。</p><div class="research-tip">${icon('spark',16)}<b>使用提示</b><ul><li>图表类型不选时，请在描述中说明需要的图表类型与用途。</li><li>可记录图形元素、标注、布局与各部分关系。</li><li>需求仅在当前页面暂存，请导出后保管。</li></ul></div></section></div><aside class="research-commerce-side"><div class="research-side-filters"><span>专业图表 · 需求准备</span></div><div class="rdc-brief-visual" aria-hidden="true">${icon('grid',42)}<span>元素</span><span>关系</span><span>标注</span></div><h3>让绘图需求更清晰</h3><ol><li>说明图表的用途、读者与使用场景。</li><li>请具体说明结构、实体、连接关系与标注要求。</li><li>基础图表和公式编辑可在本地使用，完成后请保存或导出。</li></ol></aside></div>`;}
function drawFormula(){root.innerHTML=`<div class="research-space research-commerce rdc-research-space ${mode==='pro'?'rdc-research-pro':'rdc-research-formula'}">${toolBanner('research',{extraClass:'detail-service-banner',description:'编辑 LaTeX 文本，整理常用公式并预览与导出。',actions:`<a class="btn secondary" href="#assets?scope=local">${icon('chart',17)} 我的图表</a>`})}${nav()}${workflow(mode)}<div class="research-commerce-main"><section class="rdc-formula-toolbox"><div class="rdc-dialog-section-head"><b>符号工具箱</b><span>点击插入常用 LaTeX 表达</span></div><div class="research-formula-toolbar" data-scroll-key="research-formula-toolbar-1">${formulaTokens.map(([label],i)=>`<button data-formula-token="${i}" title="插入${label}">${label}</button>`).join('')}</div></section><section class="card research-formula-card"><div class="hub-card-heading"><div><span class="research-panel-step">FORMULA STUDIO · 公式工作区</span><h2>公式编辑</h2></div><span class="hub-badge">LaTeX 文本</span></div><div class="research-formula-editor"><aside><b>常用公式模板</b><p>数学 · 基础几何</p>${['三角形的内角和','三角形的周长','三角形的面积','圆柱的体积','圆的半径','圆的周长'].map((x,i)=>`<button data-formula-preset="${i}"><span>${x}</span><code>${['180°','C = a + b + c','S = ½ah','V = πr²h','r = d⁄2','C = 2πr'][i]}</code></button>`).join('')}</aside><div class="rdc-formula-workbench"><div class="rdc-editor-label"><label for="research-formula-input">公式源码</label><span>LaTeX</span></div><textarea id="research-formula-input" data-formula rows="8" aria-label="公式文本" placeholder="在此输入或修改 LaTeX 代码…">${esc(formula)}</textarea><p class="hub-footnote">输入 LaTeX 代码，预览文本并复制或导出 SVG。当前为文本呈现，复杂公式请在专业编辑器中核对。</p><div class="research-formula-preview"><h3>公式文本预览 <span>文本呈现</span></h3><div id="formula-preview">${esc(formula||'在左侧输入公式后预览')}</div></div><div class="research-actions rdc-formula-actions"><button class="btn secondary" data-action="formula-copy">复制公式</button><button class="btn primary" data-action="formula-export">导出 SVG</button></div></div></div></section></div></div>`;}
function draw(){return withStableView(root,drawContents);}function drawContents(){if(mode==='stats'){drawStatistics();return;}if(mode==='pro'){drawPro();return;}if(mode==='formula'){drawFormula();return;}root.innerHTML=`<div class="research-space research-basic rdc-research-space rdc-research-basic">${toolBanner('research',{extraClass:'detail-service-banner',description:'整理研究数据，制作论文与汇报图表。',actions:`<a class="btn secondary" href="#assets?scope=local">${icon('chart',17)} 我的图表</a>`})}${nav()}${workflow('basic')}<div class="research-grid"><section class="card research-card rdc-data-panel"><div class="hub-card-heading"><div><span class="research-panel-step">DATA INPUT · 数据准备</span><h2>准备研究数据</h2><p class="rdc-panel-description">输入数值，让图表跟随你的数据更新。</p></div><span class="hub-badge rdc-source-state ${chart.example?'is-example':''}" id="research-source">${chart.example?'示例数据':'用户数据'}</span></div><div class="research-tabs" data-scroll-key="research-tabs-1" role="group" aria-label="数据输入方式">${[['manual','手动输入'],['paste','粘贴表格'],['csv','导入 CSV']].map(([id,n])=>`<button data-tab="${id}" class="${tab===id?'active':''}" aria-pressed="${tab===id}">${icon(id==='csv'?'upload':'file',15)} ${n}</button>`).join('')}</div><div class="rdc-data-fields"><label class="research-field">所属项目<select data-option="projectId" aria-label="所属项目"><option value="">未归入项目</option>${projects().map(p=>`<option value="${esc(p.id)}" ${chart.projectId===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label><label class="research-field">图表标题<input data-option="title" aria-label="图表标题" maxlength="120" value="${esc(chart.title)}"></label></div>${tab==='manual'?`<div class="rdc-table-heading"><b>数据编辑表</b><span>${chart.type==='scatter'?'第一列为数值 X，其余列为数值系列':'第一列为类别，其余列为数值系列'}</span></div><div class="research-table-wrap" data-scroll-key="research-table-wrap-1"><table class="research-table"><thead><tr><th scope="col">#</th>${chart.headers.map((h,j)=>`<th scope="col"><input data-header="${j}" aria-label="第 ${j+1} 列名称" maxlength="40" value="${esc(h)}"></th>`).join('')}<th scope="col">操作</th></tr></thead><tbody>${chart.rows.map((row,i)=>`<tr><th scope="row">${i+1}</th>${row.map((v,j)=>`<td><input data-row="${i}" data-col="${j}" aria-label="第 ${i+1} 行第 ${j+1} 列" maxlength="${j===0?40:30}" value="${esc(v)}" ${j?'inputmode="decimal"':''}></td>`).join('')}<td><button data-remove-row="${i}" aria-label="移除第 ${i+1} 行" ${chart.rows.length===1?'disabled':''}>×</button></td></tr>`).join('')}</tbody></table></div><div class="research-actions"><button class="btn secondary" data-action="add-row">${icon('plus',14)} 添加行</button><button class="btn secondary" data-action="add-series">${icon('plus',14)} 添加系列</button>${chart.headers.length>2?'<button class="btn secondary" data-action="remove-series">移除最后系列</button>':''}</div>`:tab==='paste'?`<label class="research-field">粘贴 CSV 或制表符表格<textarea id="research-paste" rows="9" maxlength="250000" placeholder="类别,方案 A,方案 B&#10;样本一,18,22"></textarea></label><button class="btn secondary" data-action="apply-paste">应用表格</button><p class="hub-footnote">第一行为表头。应用成功才替换数据；空值与非数字会报错。</p>`:`<label class="research-drop">${icon('upload',32)}<b>${busy?'正在读取…':'点击或拖入 CSV 文件'}</b><span>UTF-8 CSV · 最大 1MB · 最多 200 行、5 个数值系列</span><input type="file" id="research-file" accept=".csv,.tsv,text/csv" aria-label="导入 CSV 文件"></label><p class="hub-footnote">支持逗号 CSV、制表符表格和带引号的单元格。</p>`}<div class="research-data-note"><span>${chart.example?'示例或基于示例修改的数据，不代表真实研究。':'图表仅依据你提供的数值绘制。'}</span><b id="research-count">${chart.rows.length} 行 · ${chart.headers.length-1} 个系列</b></div><div class="research-actions rdc-main-actions"><button class="btn primary" data-action="save">保存图表</button><button class="btn secondary" data-action="csv">导出数据</button><button class="btn secondary" data-action="new">新建空白</button><button class="btn secondary" data-action="example">使用示例</button></div><p id="research-status" class="hub-footnote rdc-save-status" role="status">${dirty?'有未保存修改。':'点击“保存图表”后可在当前浏览器继续编辑。'}</p></section><section class="card research-card rdc-preview-panel"><div class="hub-card-heading"><div><span class="research-panel-step">VISUAL OUTPUT · 图表画布</span><h2>图表与样式预览</h2><p class="rdc-panel-description">先核对图表，再选择适合论文的呈现。</p></div><div class="research-actions"><button class="btn secondary" data-action="svg">导出 SVG</button><button class="btn secondary" data-action="png">导出 PNG</button></div></div><div class="research-tabs" data-scroll-key="research-tabs-2" role="group" aria-label="图表类型">${chartTypes.map(([id,n])=>`<button data-type="${id}" class="${chart.type===id?'active':''}" aria-pressed="${chart.type===id}">${n}</button>`).join('')}</div><div class="rdc-canvas-caption"><span>${icon('chart',15)} 图表画布</span><small>按当前表格数值绘制</small></div><div id="research-chart" class="research-chart"></div><p id="research-error" class="research-error" role="alert"></p><div class="rdc-settings-heading"><b>图表样式</b><span>调整样式，不改动原始数值</span></div><div class="research-settings">${field('xLabel','X 轴名称')}${field('yLabel','Y 轴名称')}${field('unit','单位',20)}<label>配色<select data-option="palette" aria-label="配色">${[['blue','学术蓝 / 青'],['mono','蓝灰'],['nature','自然配色']].map(([v,n])=>`<option value="${v}" ${chart.palette===v?'selected':''}>${n}</option>`).join('')}</select></label><label>字号<select data-option="fontSize" aria-label="字号">${[12,14,16,18].map(n=>`<option value="${n}" ${chart.fontSize===n?'selected':''}>${n}px</option>`).join('')}</select></label><label>导出尺寸<select data-option="width" aria-label="导出尺寸">${[1200,1600,2400].map(n=>`<option value="${n}" ${chart.width===n?'selected':''}>${n} × ${n*.625}</option>`).join('')}</select></label><label>柱状图系列<select data-option="series" aria-label="柱状图系列">${chart.headers.slice(1).map((h,i)=>`<option value="${i}" ${Number(chart.series)===i?'selected':''}>${esc(h)}</option>`).join('')}</select></label><label class="research-check"><input type="checkbox" data-option="legend" ${chart.legend?'checked':''}> 显示图例</label><label class="research-check"><input type="checkbox" data-option="grid" ${chart.grid?'checked':''}> 显示网格</label></div><p class="hub-footnote">单柱状图展示所选系列；分组和折线展示全部系列。散点图要求第一列为数值 X。长类别名称会缩略，SVG 内含完整数据提示。</p><p class="hub-footnote">样式设置不改变原始数据。多行图表会减少坐标标签，建议先筛选关键数据。</p></section></div><section class="card research-card"><div class="hub-card-heading"><h2>最近图表</h2><a href="#assets?scope=local">查看全部 →</a></div><div class="research-recents">${list(keys.drafts).filter(d=>d.tool==='research').sort((a,b)=>String(b.updatedAt).localeCompare(String(a.updatedAt))).slice(0,3).map(d=>`<a href="#draft/${esc(d.id)}">${icon('chart',24)}<div><b>${esc(d.title)}</b><small>${d.chart?.example?'示例材料 · ':''}${formatDate(d.updatedAt)}</small><span>继续编辑 →</span></div></a>`).join('')||'<div class="research-empty">'+icon('chart',28)+'<p>尚无保存的图表，完成绘图后可在这里继续编辑。</p></div>'}</div></section><div class="research-backup">${icon('shield',22)}<div><b>数据有据，图表可复用</b><p>本地处理，不自动上传；统计检验、显著性分析和云端同步尚未接入。</p></div><button class="btn secondary" data-action="backup">导出图表备份</button></div></div>`;updateChart();bindDrop();}
function mark(){if(mode==='pro'||mode==='formula')supplementalDirty=true;else dirty=true;const status=$('#research-status');if(status)status.textContent='有未保存修改，请保存图表或导出备份。';}
function updateChart(){try{const svg=renderChart(chart);$('#research-chart').innerHTML=svg;$('#research-error').textContent='';root.querySelectorAll('[data-action="svg"],[data-action="png"]').forEach(b=>b.disabled=busy);}catch(e){$('#research-chart').innerHTML='<div class="research-empty">'+icon('chart',30)+'<p>请修正数据后查看图表。</p></div>';$('#research-error').textContent=e.message;root.querySelectorAll('[data-action="svg"],[data-action="png"]').forEach(b=>b.disabled=true);}}
function inputChange(e){const t=e.target;if(t.dataset.formula!==undefined){formula=t.value;const preview=$('#formula-preview');if(preview)preview.textContent=formula||'在左侧输入公式后预览';mark();return;}if(t.dataset.proDescription!==undefined){proDescription=t.value;const counter=t.parentElement?.querySelector('small');if(counter)counter.textContent=`${t.value.length}/2000`;mark();return;}if(t.dataset.row!==undefined){chart.rows[Number(t.dataset.row)][Number(t.dataset.col)]=t.value;mark();updateChart();}else if(t.dataset.header!==undefined){chart.headers[Number(t.dataset.header)]=t.value;const options=$('[data-option="series"]')?.options;if(options)for(let i=0;i<options.length;i++)options[i].textContent=chart.headers[i+1];mark();updateChart();}else if(t.dataset.option){let v=t.type==='checkbox'?t.checked:t.value;if(['width','fontSize','series'].includes(t.dataset.option))v=Number(v);chart[t.dataset.option]=v;if(t.dataset.option==='width')chart.height=v*.625;mark();updateChart();}else if(t.id==='research-file')readFile(t.files[0]);}
function freeze(value){root.querySelectorAll('input,select,textarea,button').forEach(el=>{if(value){el.dataset.researchDisabled=String(el.disabled);el.disabled=true;}else if(el.dataset.researchDisabled!==undefined){el.disabled=el.dataset.researchDisabled==='true';delete el.dataset.researchDisabled;}});}
function bindDrop(){const drop=$('.research-drop');if(!drop)return;drop.addEventListener('dragover',e=>{e.preventDefault();drop.classList.add('drag');});drop.addEventListener('dragleave',()=>drop.classList.remove('drag'));drop.addEventListener('drop',e=>{e.preventDefault();drop.classList.remove('drag');if(e.dataTransfer.files.length!==1)return ctx.notify('每次请选择一个文件。');readFile(e.dataTransfer.files[0]);});}
function replaceData(parsed,name){if(dirty&&!confirm('替换当前表格数据？建议先保存图表或导出备份。'))return;if(chart.example)chart.title=name==='粘贴表格'?'研究数据图表':name.replace(/\.(csv|tsv)$/i,'').slice(0,120)||'研究数据图表';Object.assign(chart,parsed,{example:false,fileName:name,series:0});if(chart.type==='scatter')chart.type='grouped';mark();tab='manual';draw();ctx.notify('已导入并核对数据格式。');}
async function readFile(file){const epoch=researchEpoch;if(!file||busy)return;if(!/\.(csv|tsv)$/i.test(file.name)||file.size>1024*1024)return ctx.notify('请选择 1MB 以内的 CSV 或 TSV。');busy=true;freeze(true);try{const text=new TextDecoder('utf-8',{fatal:true}).decode(await file.arrayBuffer());if(epoch!==researchEpoch)return;const parsed=parseTable(text);busy=false;replaceData(parsed,file.name);}catch(e){if(epoch===researchEpoch)ctx.notify(e.message||'读取失败，请使用 UTF-8 CSV。');}finally{if(epoch===researchEpoch){busy=false;freeze(false);}}}
function save(){try{renderChart(chart);const rows=list(keys.drafts),old=rows.find(d=>String(d.id)===String(chart.id)),now=new Date().toISOString(),id=chart.id||crypto.randomUUID(),item={...old,id,title:chart.title.trim(),tool:'research',kind:'科研图表',projectId:chart.projectId,stage:'chart',createdAt:old?.createdAt||now,updatedAt:now,date:formatDate(now),text:csvText(chart),material:csvText(chart),chart:structuredClone({...chart,id})};write(keys.drafts,old?rows.map(d=>d.id===old.id?item:d):[item,...rows]);chart.id=id;dirty=false;try{recordTask({id:'draft-'+id,title:item.title,kind:'科研图表保存',status:'completed',projectId:item.projectId,url:'#draft/'+id});}catch{}draw();ctx.notify('图表和原始数据已保存到当前浏览器。');}catch(e){ctx.notify(e.message||'保存失败，请导出备份。');}}
async function png(){const epoch=researchEpoch;const svg=renderChart(chart),blob=new Blob([svg],{type:'image/svg+xml;charset=utf-8'}),url=URL.createObjectURL(blob);busy=true;freeze(true);try{const img=new Image();await new Promise((resolve,reject)=>{img.onload=resolve;img.onerror=()=>reject(new Error('PNG 绘制失败，请导出 SVG。'));img.src=url;});if(epoch!==researchEpoch)return;const canvas=document.createElement('canvas');canvas.width=chart.width;canvas.height=chart.height;const context=canvas.getContext('2d');if(!context)throw new Error('当前浏览器无法导出 PNG，请导出 SVG。');context.drawImage(img,0,0);const imageBlob=await new Promise(r=>canvas.toBlob(r,'image/png'));if(epoch!==researchEpoch)return;if(!imageBlob)throw new Error('PNG 生成失败。');download(chart.title+'.png',imageBlob,'image/png');ctx.notify('已导出 PNG。');}finally{URL.revokeObjectURL(url);if(epoch===researchEpoch){busy=false;freeze(false);}}}
async function actions(e){const b=e.target.closest('button');if(!b)return;if(busy)return ctx.notify('正在处理，请稍候。');try{if(b.dataset.mode){mode=b.dataset.mode;draw();return;}if(b.dataset.formulaPreset!==undefined){const presets=['180°','C = a + b + c','S = ½ah','V = πr²h','r = d⁄2','C = 2πr'];formula=presets[Number(b.dataset.formulaPreset)]||'';draw();mark();return;}if(b.dataset.formulaToken!==undefined){const token=formulaTokens[Number(b.dataset.formulaToken)]?.[1];if(!token)return;formula+=(formula?' ':'')+token;draw();mark();return;}if(b.dataset.proType!==undefined){proType=b.dataset.proType;root.querySelectorAll('[data-pro-type]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b));});mark();return;}if(b.dataset.tab){tab=b.dataset.tab;draw();return;}if(b.dataset.type){chart.type=b.dataset.type;mark();draw();return;}if(b.dataset.removeRow!==undefined){chart.rows.splice(Number(b.dataset.removeRow),1);mark();draw();return;}switch(b.dataset.action){case 'pro-generate':{const description=root.querySelector('[data-pro-description]')?.value.trim();if(!description)throw new Error('请先填写图表描述。');ctx.notify('需求已填写，建议补齐用途、结构与标注后导出保管。');mark();break;}case 'pro-export':{const description=proDescription.trim();if(!description)throw new Error('请先填写图表描述。');download('PaperKnow-专业绘图需求.txt',['PaperKnow 专业绘图需求','领域：'+(proTypes[Number(proType)]&&proType!==''?proTypes[Number(proType)]:'未选择'),'',description,'','此文件为用户整理的绘图需求，不是已生成的图表。'].join('\n'));ctx.notify('已发起绘图需求文本下载，请确认文件已保存。');break;}case 'formula-copy':if(!formula.trim())throw new Error('请先输入公式。');if(typeof navigator.clipboard?.writeText!=='function')throw new Error('当前浏览器无法自动复制，请在编辑框中手动复制。');try{await navigator.clipboard.writeText(formula);}catch{throw new Error('复制未成功，请在编辑框中手动复制公式。');}ctx.notify('公式已复制。');break;case 'formula-export':if(!formula.trim())throw new Error('请先输入公式。');download('公式.svg',`<svg xmlns="http://www.w3.org/2000/svg" width="1000" height="300"><text x="20" y="160" font-size="42">${esc(formula||'')}</text></svg>`,'image/svg+xml');ctx.notify('已导出公式 SVG。');break;case 'add-row':if(chart.rows.length>=200)throw new Error('最多 200 行。');chart.rows.push(chart.headers.map(()=>''));mark();draw();break;case 'add-series':if(chart.headers.length>=6)throw new Error('最多 5 个数值系列。');chart.headers.push('系列 '+chart.headers.length);chart.rows.forEach(r=>r.push(''));mark();draw();break;case 'remove-series':if(!confirm('移除最后一个系列及其数值？未保存前不影响原有记录。'))return;chart.headers.pop();chart.rows.forEach(r=>r.pop());chart.series=Math.min(chart.series,chart.headers.length-2);mark();draw();break;case 'apply-paste':replaceData(parseTable($('#research-paste').value),'粘贴表格');break;case 'save':save();break;case 'svg':download(chart.title+'.svg',renderChart(chart),'image/svg+xml;charset=utf-8');ctx.notify('已导出 SVG。');break;case 'png':await png();break;case 'csv':download((chart.title||'图表数据')+'.csv',csvText(chart),'text/csv;charset=utf-8');ctx.notify('已导出数据。');break;case 'stats-csv':download((chart.title||'科研计算')+'-描述统计.csv',statCsv(statistics()),'text/csv;charset=utf-8');ctx.notify('已导出描述统计 CSV。');break;case 'stats-json':download((chart.title||'科研计算')+'-描述统计.json',JSON.stringify({title:chart.title,source:chart.example?'示例数据':'用户数据',rows:chart.rows.length,series:statistics(),note:'本地描述统计，不等同于显著性检验。'},null,2),'application/json');ctx.notify('已导出描述统计 JSON。');break;case 'backup':download((chart.title||'图表')+'-PaperKnow.json',JSON.stringify(chart,null,2),'application/json');break;case 'new':case 'example':if(dirty&&!confirm('放弃当前未保存的图表修改？'))return;chart=exampleChart();if(b.dataset.action==='new')Object.assign(chart,{title:'',headers:['类别','数值'],rows:[['','']],type:'bar',example:false,xLabel:'类别'});dirty=false;tab='manual';draw();break;}}catch(error){ctx.notify(error.message||'操作失败。');}}
